const { W, N, PZ, PW, PH, CARD_W, CARD_Y } = PP.dims;
const CARD_H = (CARD_W * 4) / 7;
const ANG = new Array(N).fill(0);                       // the leaves' angles, set by the riffle each frame

/* the member card, front only: black, 22 hairline rings lit on the diagonal, wordmark, name, number */
function drawCard() {
  const CW = 1024, CH = 585, k = CH / 200;
  const [c, x] = mk(CW, CH);
  x.save(); x.beginPath(); x.roundRect(2, 2, CW - 4, CH - 4, 46); x.clip();
  x.fillStyle = "#0B0B0B"; x.fillRect(0, 0, CW, CH);
  const cx = (162 / 350) * CW, cy = CH / 2;
  x.lineWidth = 2.2;
  for (let i = 0; i < 22; i++) {
    const r = (18 + i * 4.5) * k;
    const g = x.createLinearGradient(cx + r, cy - r, cx - r, cy + r);
    g.addColorStop(0, "rgba(207,171,113,.85)"); g.addColorStop(0.28, "rgba(207,171,113,.1)");
    g.addColorStop(0.72, "rgba(207,171,113,.1)"); g.addColorStop(1, "rgba(207,171,113,.85)");
    x.strokeStyle = g; x.beginPath(); x.arc(cx, cy, r, 0, TAU); x.stroke();
  }
  x.restore();
  x.strokeStyle = "rgba(255,247,232,.12)"; x.lineWidth = 3; x.beginPath(); x.roundRect(2, 2, CW - 4, CH - 4, 46); x.stroke();
  if (wordImg) { const w = CW * 0.23, h = (w * 237) / 524; x.drawImage(wordImg, CW * 0.94 - w, CH * 0.095, w, h); }
  x.fillStyle = "#FFF7E8"; x.font = FONT(400, 66);
  const nameW = x.measureText("Reserved").width;
  x.font = FONT(400, 38); const titleW = x.measureText("Founding Member").width + 14 * 2.3;
  const colW = Math.max(nameW, titleW), colC = CW * 0.055 + colW / 2;
  x.font = FONT(400, 66); x.textAlign = "center"; x.fillText("Reserved", colC, CH * 0.9 - 58);
  x.fillStyle = "rgba(255,247,232,.62)"; x.font = FONT(400, 38); tracked(x, "Founding Member", colC, CH * 0.9, 2.3, "center");
  x.fillStyle = "#FFF7E8"; x.font = FONT(400, 66); tracked(x, "LCC-····", CW * 0.94, CH * 0.9 - 58, 3, "right");
  return c;
}

/* the card, as a hologram rising out of page 12 */
const cardMat = new THREE.ShaderMaterial({
  uniforms: { map: { value: tex(drawCard()) }, uReveal: { value: 0 }, uHolo: { value: 1 }, uTime: { value: 0 }, uSheen: { value: -1 } },
  vertexShader: `varying vec2 vUv; varying vec3 vN; varying vec3 vV;
    void main(){ vUv = uv; vec4 mv = modelViewMatrix * vec4(position, 1.0); vN = normalize(normalMatrix * normal); vV = normalize(-mv.xyz); gl_Position = projectionMatrix * mv; }`,
  fragmentShader: `uniform sampler2D map; uniform float uReveal, uHolo, uTime, uSheen; varying vec2 vUv; varying vec3 vN; varying vec3 vV;
    void main(){
      vec4 c = texture2D(map, vUv);
      float front = uReveal * 1.15 - 0.05;
      float vis = 1.0 - smoothstep(front - 0.03, front, vUv.y);
      float live = step(0.001, uReveal) * step(uReveal, 0.999);
      float edge = (1.0 - smoothstep(0.0, 0.02, abs(vUv.y - front))) * live;
      float scan = 0.8 + 0.2 * sin(vUv.y * 620.0 - uTime * 9.0);
      float flick = 0.93 + 0.07 * sin(uTime * 37.0) * sin(uTime * 13.0);
      float fres = pow(1.0 - clamp(abs(dot(vN, vV)), 0.0, 1.0), 2.0);
      vec3 tint = vec3(0.81, 0.67, 0.44);
      vec3 col = mix(c.rgb, c.rgb * scan + tint * (0.10 + 0.6 * fres) * scan, uHolo);
      col += vec3(1.0, 0.9, 0.72) * edge * 1.4;
      float sw = 1.0 - smoothstep(0.0, 0.09, abs(vUv.x + vUv.y * 0.6 - uSheen));
      col += vec3(1.0, 0.95, 0.86) * sw * 0.16 * (1.0 - uHolo);
      float a = c.a * max(vis * mix(1.0, (0.55 + 0.3 * scan) * flick, uHolo), edge);
      gl_FragColor = vec4(col, a);
      #include <colorspace_fragment>
    }`,
  transparent: true, depthWrite: false, toneMapped: false,
});
const card = new THREE.Mesh(new THREE.PlaneGeometry(CARD_W, CARD_H), cardMat);
card.visible = false; book.add(card);
const CARD_HOME = new THREE.Vector3(0.018, CARD_Y, PZ + 0.006);
const beamGeo = new THREE.BufferGeometry(); beamGeo.setAttribute("position", new THREE.BufferAttribute(new Float32Array(24), 3));
const beamMat = new THREE.LineBasicMaterial({ color: 0xcfab71, transparent: true, opacity: 0, depthWrite: false });
const beam = new THREE.LineSegments(beamGeo, beamMat); beam.frustumCulled = false; book.add(beam);
const corners = [[-1, -1], [1, -1], [1, 1], [-1, 1]].map(([a, b]) => new THREE.Vector3((a * CARD_W) / 2, (b * CARD_H) / 2, 0));

