/* sized from the canvas (100lvh), never from the keyboard or the address bar */
function resize() {
  const w = canvas.clientWidth || innerWidth, h = canvas.clientHeight || innerHeight, a = w / h;
  if (w === L.w && h === L.h) return;
  renderer.setSize(w, h, false);
  camera.aspect = a;
  const tanH = Math.tan((camera.fov / 2) * D2R);
  L.w = w; L.h = h;
  L.portrait = !(a >= 0.8 && w >= 561);   // same rule as the CSS: wide enough and not tall = words left, object right
  L.dist = L.portrait ? Math.max(12.5, 4.5 / (2 * tanH * a)) : Math.max(12.5, 6.4 / (2 * tanH * a));
  POSE = poses(L.portrait);
}
