  const t = now / 1000, p = S.p;
  const I = RM ? (S.introStart ? (now - S.introStart) / 1000 : 0) : 99;
  const s = Math.min(1, p / 0.74);
  const kF = seg(p, 0.775, 0.845);
  const passVis = p < 0.8 ? 1 - seg(p, 0.74, 0.772) : seg(p, 0.832, 0.872);   // the passport steps out, then back

  let P = lerpPose(POSE.hero, POSE.globe, seg(s, 0.11, 0.17));
